import java.lang.reflect.Field;
import java.util.*;

public class Main {
    interface Repo { String find(long id); }

    static class RepoImpl implements Repo {
        public String find(long id) { return "user-" + id; }
    }

    // ① 构造器注入：依赖不可变，缺依赖无法构造
    static class ServiceCtor {
        private final Repo repo;
        ServiceCtor(Repo repo) {
            this.repo = Objects.requireNonNull(repo, "repo must not be null");
        }
        String name(long id) { return repo.find(id); }
    }

    // ② 字段注入：容器外 new 出来时字段为 null
    static class ServiceField {
        private Repo repo;
        String name(long id) { return repo.find(id); }
    }

    // ③ setter 注入：可重配，但存在半初始化风险
    static class ServiceSetter {
        private Repo repo;
        void setRepo(Repo r) { this.repo = r; }
        String name(long id) { return repo == null ? "NOT_INJECTED" : repo.find(id); }
    }

    static void injectField(Object target, String field, Object value) throws Exception {
        Field f = target.getClass().getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    public static void main(String[] args) throws Exception {
        Repo repo = new RepoImpl();

        System.out.println("=== constructor injection ===");
        ServiceCtor a = new ServiceCtor(repo);
        System.out.println("  wired outside container  : " + a.name(7));
        try {
            new ServiceCtor(null);
            System.out.println("  null dependency accepted (unexpected)");
        } catch (NullPointerException e) {
            System.out.println("  null dependency rejected at construction : " + e.getMessage());
        }

        System.out.println();
        System.out.println("=== field injection ===");
        ServiceField b = new ServiceField();
        System.out.println("  before injection, repo is null : " + (b.repo == null));
        try {
            b.name(7);
            System.out.println("  call succeeded (unexpected)");
        } catch (NullPointerException e) {
            System.out.println("  calling it now throws NullPointerException (半初始化对象)");
        }
        injectField(b, "repo", repo);
        System.out.println("  after reflective injection      : " + b.name(7));

        System.out.println();
        System.out.println("=== setter injection ===");
        ServiceSetter c = new ServiceSetter();
        System.out.println("  before setter : " + c.name(7));
        c.setRepo(repo);
        System.out.println("  after setter  : " + c.name(7));

        System.out.println();
        System.out.println("=== comparison ===");
        System.out.printf("  %-14s %-12s %-14s %s%n", "style", "final?", "container-free", "fail-fast on missing dep");
        System.out.printf("  %-14s %-12s %-14s %s%n", "constructor", "yes", "yes", "yes");
        System.out.printf("  %-14s %-12s %-14s %s%n", "setter", "no", "yes", "no");
        System.out.printf("  %-14s %-12s %-14s %s%n", "field", "no", "no (needs reflection)", "no");
    }
}
